solutionCode:
pub fn o_numero_na_tela(caixa: Option<i32>) -> i32 {
    match caixa {
        Some(v) => v,
        None => 0,
    }
}

testsCode:
use desafio::o_numero_na_tela;

#[test]
fn testa_o_nove_na_tela_da_caixa_cheia() {
    assert_eq!(o_numero_na_tela(Some(9)), 9);
}

#[test]
fn testa_o_zero_na_tela_da_caixa_vazia() {
    assert_eq!(o_numero_na_tela(None), 0);
}
